# Not public: what the modules, which live in each app, call in the library.
# A version of its own keeps them apart from the API: an app's own code must
# not reach them, and check-exports.sh says so if it does.
LIBREAKTOR_PRIVATE_0 {
  global:
    reaktor_a11y_changes;
    reaktor_a11y_role_name;
    reaktor_a11y_tree;
    reaktor_app_frame;
    reaktor_app_ident;
    reaktor_app_size;
    reaktor_asset_load;
    reaktor_asset_register;
