    reaktor_c_locale_put;
    reaktor_font_glyph;
    reaktor_font_valid;
    reaktor_frame_settled;
    reaktor_free;
    reaktor_ft_open;
    reaktor_ft_size;
    reaktor_grow;
    reaktor_launch_icon;
    reaktor_layout_info;
    reaktor_layout_rect;
    reaktor_main_app;
    reaktor_path;
    reaktor_path_leaf;
    reaktor_read_file;
    reaktor_restyle;
    reaktor_save_mode;
    reaktor_scale;
    reaktor_set_scale;
    reaktor_style_loads;
    reaktor_utf8_clean;
